SELECT ?tsId ?class WHERE {
  ?zp brick:hasTag/ref:label "Perimeter_mid_ZN_3" ;
     ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?tsId .
  ?point brick:isA ?class .
}

SELECT ?p ?class WHERE {
  ?p brick:hasTag/ref:label ?lbl .
  FILTER (CONTAINS(?lbl, "Perim") || CONTAINS(?lbl, "ZN_3"))
  ?p brick:isA ?class .
}
LIMIT 50

